    public sealed partial class NavigationPhysicalBodyTests
    {
        [TestCase(1)][TestCase(2)][TestCase(3)][TestCase(4)][TestCase(5)][TestCase(6)][TestCase(7)]
        public void OptionalMetadataLeafPreservesOnlySelectedFieldsAndRejectsForeignBeforeAllocation(int mask)
        {
            var budget=new NavigationRetentionBudget();Assert.True(budget.TryOpenScope(NavigationPreparationKind.Admission,1,1,out var scope));var r=scope.OwnedReservation();
            var c=new NavClearanceProfile("ground",1,"ground",1,.25);var p=new NavGraphProfile(new string('a',64),"distance",1,1);var l=new NavGraphCompileLimits(2000,2000,10000);
            var leaf=NavGraphMetadata.CopyOptionalUnowned((mask&1)!=0?c:null,(mask&2)!=0?p:null,(mask&4)!=0?l:null,r);Assert.NotNull(leaf);Assert.AreEqual((mask&1)!=0,leaf.Clearance!=null);Assert.AreEqual((mask&2)!=0,leaf.Profile!=null);Assert.AreEqual((mask&4)!=0,leaf.Limits!=null);
            if(leaf.Clearance!=null)Assert.AreSame(leaf,NavMetadataOwnership.Require(leaf.Clearance,r));if(leaf.Profile!=null)Assert.AreSame(leaf,NavMetadataOwnership.Require(leaf.Profile,r));if(leaf.Limits!=null)Assert.AreSame(leaf,NavMetadataOwnership.Require(leaf.Limits,r));
            long physical=budget.PhysicalBytes,held=budget.HeldBytes;Assert.Null(NavGraphMetadata.CopyOptionalUnowned(leaf.Clearance,leaf.Profile,leaf.Limits,r));Assert.AreEqual(physical,budget.PhysicalBytes);Assert.AreEqual(held,budget.HeldBytes);
            var foreign=new NavigationRetentionBudget();Assert.True(foreign.TryOpenScope(NavigationPreparationKind.Admission,1,1,out var f));Assert.Throws<ArgumentException>(()=>NavGraphMetadata.CopyOptionalUnowned(leaf.Clearance,leaf.Profile,leaf.Limits,f.OwnedReservation()));Assert.Zero(foreign.PhysicalBytes);Assert.AreEqual(NavigationRetentionBudget.ScopeBytes,f.HeldBytes);f.Discard();
            scope.Attach(leaf);scope.Commit(leaf,_=>{});var bytes=CaptureGraph(budget,leaf);long charge=budget.PhysicalBytes;leaf.Release();leaf=null;Assert.Zero(budget.PhysicalBytes);
            var cold=new NavigationRetentionBudget();Assert.True(cold.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var decode));var restored=(NavGraphMetadata)Decode(bytes,decode.OwnedReservation());decode.Attach(restored);decode.Commit(restored,_=>{});Assert.AreEqual(charge,cold.PhysicalBytes);CollectionAssert.AreEqual(bytes,CaptureGraph(cold,restored));restored.Release();Assert.Zero(cold.PhysicalBytes);Assert.Zero(cold.HeldBytes);
        }
        [TestCase(false)][TestCase(true)]
        public void ExternalRecipeColdBodyKeepsExactSharedMetadataSelectorsAndNextCompiler(bool separate)
        {
            var hot=new NavigationRetentionBudget();Assert.True(hot.TryOpenScope(NavigationPreparationKind.Admission,1,1,out var birth));var r=birth.OwnedReservation();var provider=LayeredNavigationProvider.CopyOwned((LayeredNavigationProvider)NavigationAdmission.CertifiedFlatProvider(new NavGeometry(3,new NavObstacle[0],1)),r);
            var c=new NavClearanceProfile("ground",1,"ground",1,.25);var p=new NavGraphProfile(new string('a',64),"distance",1,1);var l=new NavGraphCompileLimits(2000,2000,10000);
            var cm=NavGraphMetadata.CopyOptionalUnowned(c,separate?null:p,separate?null:l,r);var pm=separate?NavGraphMetadata.CopyOptionalUnowned(null,p,null,r):cm;var lm=separate?NavGraphMetadata.CopyOptionalUnowned(null,null,l,r):cm;
            var region=NavTerminalRegion.CopyOwned(new NavTerminalRegion("arrival-source",1,new NavLocation(new NavPoint(2,0),NavLocation.FlatSurface),new[]{new NavLocation(new NavPoint(2,0),NavLocation.FlatSurface)}),r);
            NavScheduledRequest Make(int entity){var sub=new NavRouteSubscription(1,1,1,1,0,1,entity,1,1,1,1,new NavLocation(new NavPoint(-2,0),NavLocation.FlatSurface),new NavLocation(new NavPoint(2,0),NavLocation.FlatSurface),"HOLD");var recipe=NavScheduledRequest.CreateOwned(provider,cm.Clearance,pm.Profile,lm.Limits,region,sub,4096,r);var original=new NavScheduledRequest(provider,cm.Clearance,pm.Profile,lm.Limits,region,sub,4096);Assert.AreEqual(original.GraphKey,recipe.GraphKey);Assert.AreEqual(original.CompileKey,recipe.CompileKey);Assert.AreEqual(original.ArtifactKey,recipe.ArtifactKey);Assert.AreEqual(sub.StableKey,recipe.Subscription.StableKey);return recipe;}
            var first=Make(1);var second=Make(2);Assert.AreSame(first.Clearance,second.Clearance);Assert.AreSame(first.Profile,second.Profile);Assert.AreSame(first.Limits,second.Limits);Assert.AreSame(first.StorageRoot,first.Subscription.MetadataOwner);
            var bundle=NavRetainedArray<NavOwnedStorage>.Copy(new[]{first.StorageRoot,second.StorageRoot,(NavOwnedStorage)cm,pm,lm},birth.TryReserve);first.StorageRoot.ReleaseOwner();second.StorageRoot.ReleaseOwner();provider.StorageRoot.ReleaseOwner();region.StorageRoot.ReleaseOwner();cm.Release();if(separate){pm.Release();lm.Release();}birth.Attach(bundle);birth.Commit(bundle,_=>{});
            long charge=hot.PhysicalBytes;Assert.AreEqual(Unique(bundle),charge);var bytes=CaptureGraph(hot,bundle);
            byte[] Next(NavigationRetentionBudget budget,NavScheduledRequest recipe,out long physical){Assert.True(budget.TryOpenScope(NavigationPreparationKind.Solve,1,100,out var operation));var work=LayeredNavigationCompileWork.CreateOwned(recipe.Provider,recipe.Clearance,recipe.Profile,recipe.Limits,operation.OwnedReservation());work.Advance(1);work.SealPrepared();operation.Attach(work);operation.Commit(work,_=>{});var output=CaptureGraph(budget,work);physical=Unique(work);work.ReleaseOwner();return output;}
            var expected=Next(hot,first,out long nextCharge);CollectionAssert.AreEqual(bytes,CaptureGraph(hot,bundle));bundle.Release();bundle=null;first=null;second=null;cm=null;pm=null;lm=null;provider=null;region=null;Assert.Zero(hot.PhysicalBytes);Assert.Zero(hot.HeldBytes);
            var cold=new NavigationRetentionBudget();Assert.True(cold.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var decode));var restored=(NavRetainedArray<NavOwnedStorage>)Decode(bytes,decode.OwnedReservation());decode.Attach(restored);decode.Commit(restored,_=>{});var a=(NavScheduledRequest)((NavDeclarationStorage)restored[0]).Facade;var b=(NavScheduledRequest)((NavDeclarationStorage)restored[1]).Facade;Assert.AreSame(a.Clearance,b.Clearance);Assert.AreSame(a.Profile,b.Profile);Assert.AreSame(a.Limits,b.Limits);Assert.AreSame(restored[2],a.Clearance.MetadataOwner);Assert.AreSame(restored[3],a.Profile.MetadataOwner);Assert.AreSame(restored[4],a.Limits.MetadataOwner);Assert.AreEqual(charge,cold.PhysicalBytes);Assert.AreEqual(Unique(restored),cold.PhysicalBytes);CollectionAssert.AreEqual(bytes,CaptureGraph(cold,restored));CollectionAssert.AreEqual(expected,Next(cold,a,out long actualCharge));Assert.AreEqual(nextCharge,actualCharge);
            NavScheduledRequest Born(INavStorageReservation reservation)=>NavScheduledRequest.CreateOwned(a.Provider,a.Clearance,a.Profile,a.Limits,a.Region,a.Subscription,a.MaxLabels,reservation,a.Singleton);
            Assert.True(cold.TryOpenScope(NavigationPreparationKind.Admission,1,200,out var countedBirth));var counter=new Refusal(countedBirth,int.MaxValue);var born=Born(counter);countedBirth.Attach(born.StorageRoot);int sourceCalls=counter.Calls;countedBirth.Discard();Assert.AreEqual(charge,cold.PhysicalBytes);Assert.Zero(cold.HeldBytes);
            for(int nth=1;nth<=sourceCalls;nth++){Assert.True(cold.TryOpenScope(NavigationPreparationKind.Admission,1,200+nth,out var rejectedBirth));var refusal=new Refusal(rejectedBirth,nth);Assert.Throws<InvalidOperationException>(()=>Born(refusal));Assert.AreEqual(nth,refusal.Calls);rejectedBirth.Discard();Assert.AreEqual(charge,cold.PhysicalBytes);Assert.Zero(cold.HeldBytes);CollectionAssert.AreEqual(bytes,CaptureGraph(cold,restored));}
            var foreign=new NavigationRetentionBudget();Assert.True(foreign.TryOpenScope(NavigationPreparationKind.Admission,1,1,out var foreignBirth));Assert.Throws<ArgumentException>(()=>Born(foreignBirth.OwnedReservation()));Assert.Zero(foreign.PhysicalBytes);Assert.AreEqual(NavigationRetentionBudget.ScopeBytes,foreign.HeldBytes);foreignBirth.Discard();
            var malformed=CaptureGraph(cold,a.StorageRoot);malformed[17]=2;var invalid=new NavigationRetentionBudget();Assert.True(invalid.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var invalidBirth));Assert.Throws<ArgumentException>(()=>Decode(malformed,invalidBirth.OwnedReservation()));invalidBirth.Discard();Assert.Zero(invalid.PhysicalBytes);Assert.Zero(invalid.HeldBytes);
            restored.Release();restored=null;a=null;b=null;Assert.Zero(cold.PhysicalBytes);Assert.Zero(cold.HeldBytes);
            var counted=new NavigationRetentionBudget();Assert.True(counted.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var count));var all=new Refusal(count,int.MaxValue);var trial=Decode(bytes,all);count.Attach(trial);int allocations=all.Calls;count.Discard();Assert.Zero(counted.PhysicalBytes);Assert.Zero(counted.HeldBytes);
            for(int nth=1;nth<=allocations;nth++){var bad=new NavigationRetentionBudget();Assert.True(bad.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var rejected));var refusal=new Refusal(rejected,nth);Assert.Throws<InvalidOperationException>(()=>Decode(bytes,refusal));Assert.AreEqual(nth,refusal.Calls);rejected.Discard();Assert.Zero(bad.PhysicalBytes);Assert.Zero(bad.HeldBytes);Assert.Zero(bad.ActiveScopes);}
        }
    }
